CREATE TABLE energy_document (
 id INTEGER PRIMARY KEY CHECK(id=1), schema TEXT NOT NULL, name TEXT NOT NULL, version TEXT NOT NULL,
 latitude_deg REAL, longitude_deg REAL, elevation_m REAL, time_zone_hours REAL, north_axis_deg REAL, deep_ground_c REAL,
 start_month INTEGER NOT NULL CHECK(start_month BETWEEN 0 AND 255), start_day INTEGER NOT NULL CHECK(start_day BETWEEN 0 AND 255), end_month INTEGER NOT NULL CHECK(end_month BETWEEN 0 AND 255), end_day INTEGER NOT NULL CHECK(end_day BETWEEN 0 AND 255), year INTEGER NOT NULL CHECK(year BETWEEN 0 AND 65535),
 latitude_deg_ieee754_bits INTEGER NOT NULL, latitude_deg_ieee754_class TEXT NOT NULL, longitude_deg_ieee754_bits INTEGER NOT NULL, longitude_deg_ieee754_class TEXT NOT NULL, elevation_m_ieee754_bits INTEGER NOT NULL, elevation_m_ieee754_class TEXT NOT NULL, time_zone_hours_ieee754_bits INTEGER NOT NULL, time_zone_hours_ieee754_class TEXT NOT NULL, north_axis_deg_ieee754_bits INTEGER NOT NULL, north_axis_deg_ieee754_class TEXT NOT NULL, deep_ground_c_ieee754_bits INTEGER NOT NULL, deep_ground_c_ieee754_class TEXT NOT NULL
);
CREATE TABLE energy_structure_child (id INTEGER PRIMARY KEY REFERENCES energy_document(id), child_id TEXT NOT NULL, artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL);
CREATE TABLE energy_zones_child (id INTEGER PRIMARY KEY REFERENCES energy_document(id), child_id TEXT NOT NULL, artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL);
CREATE TABLE energy_referenced_model_link (id INTEGER PRIMARY KEY REFERENCES energy_document(id), artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL, role TEXT NOT NULL, pin_kind TEXT NOT NULL CHECK(pin_kind IN ('head','checkpoint','snapshot')), checkpoint_id TEXT, blob_hash TEXT, blob_size_high INTEGER CHECK(blob_size_high BETWEEN 0 AND 4294967295), blob_size_low INTEGER CHECK(blob_size_low BETWEEN 0 AND 4294967295), blob_media_type TEXT);
CREATE TABLE energy_weather_link (id INTEGER PRIMARY KEY REFERENCES energy_document(id), artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL, role TEXT NOT NULL, pin_kind TEXT NOT NULL CHECK(pin_kind IN ('head','checkpoint','snapshot')), checkpoint_id TEXT, blob_hash TEXT, blob_size_high INTEGER CHECK(blob_size_high BETWEEN 0 AND 4294967295), blob_size_low INTEGER CHECK(blob_size_low BETWEEN 0 AND 4294967295), blob_media_type TEXT);
CREATE TABLE energy_ground_month (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 11), building_surface_c REAL, shallow_c REAL, building_surface_c_ieee754_bits INTEGER NOT NULL, building_surface_c_ieee754_class TEXT NOT NULL, shallow_c_ieee754_bits INTEGER NOT NULL, shallow_c_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_zone (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), name TEXT NOT NULL, volume_m3 REAL, multiplier INTEGER NOT NULL CHECK(multiplier BETWEEN 0 AND 4294967295), conditioned INTEGER NOT NULL CHECK(conditioned IN (0,1)), part_of_total_floor_area INTEGER NOT NULL CHECK(part_of_total_floor_area IN (0,1)), volume_m3_ieee754_bits INTEGER NOT NULL, volume_m3_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_space (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), name TEXT NOT NULL, zone_id INTEGER NOT NULL CHECK(zone_id BETWEEN 0 AND 4294967295), floor_area_m2 REAL, floor_area_m2_ieee754_bits INTEGER NOT NULL, floor_area_m2_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_surface (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), name TEXT NOT NULL, zone_id INTEGER NOT NULL CHECK(zone_id BETWEEN 0 AND 4294967295), class TEXT NOT NULL CHECK(class IN ('ExteriorWall','InteriorWall','Roof','Ceiling','Floor','Interzone','Adiabatic','Ground')), construction_id INTEGER NOT NULL CHECK(construction_id BETWEEN 0 AND 4294967295), outside_boundary_kind TEXT NOT NULL CHECK(outside_boundary_kind IN ('OutdoorAir','Ground','OtherSideTemperature','Adiabatic','Interzone')), interzone_partner INTEGER CHECK(interzone_partner BETWEEN 0 AND 4294967295), sun_exposed INTEGER NOT NULL CHECK(sun_exposed IN (0,1)), wind_exposed INTEGER NOT NULL CHECK(wind_exposed IN (0,1)), multiplier INTEGER NOT NULL CHECK(multiplier BETWEEN 0 AND 4294967295));
CREATE TABLE energy_surface_vertex (id INTEGER PRIMARY KEY, surface_id INTEGER NOT NULL REFERENCES energy_surface(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), x_m REAL, y_m REAL, z_m REAL, x_m_ieee754_bits INTEGER NOT NULL, x_m_ieee754_class TEXT NOT NULL, y_m_ieee754_bits INTEGER NOT NULL, y_m_ieee754_class TEXT NOT NULL, z_m_ieee754_bits INTEGER NOT NULL, z_m_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_fenestration (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), name TEXT NOT NULL, surface_id INTEGER NOT NULL CHECK(surface_id BETWEEN 0 AND 4294967295), u_value_w_m2k REAL, shgc REAL, vlt REAL, area_m2 REAL, height_m REAL, sill_height_m REAL, frame_conductance_w_k REAL, divider_conductance_w_k REAL, overhang_depth_m REAL, overhang_offset_m REAL, fin_depth_m REAL, fin_offset_m REAL, glazing_construction_id INTEGER CHECK(glazing_construction_id BETWEEN 0 AND 4294967295),
 u_value_w_m2k_ieee754_bits INTEGER NOT NULL, u_value_w_m2k_ieee754_class TEXT NOT NULL, shgc_ieee754_bits INTEGER NOT NULL, shgc_ieee754_class TEXT NOT NULL, vlt_ieee754_bits INTEGER NOT NULL, vlt_ieee754_class TEXT NOT NULL, area_m2_ieee754_bits INTEGER NOT NULL, area_m2_ieee754_class TEXT NOT NULL, height_m_ieee754_bits INTEGER NOT NULL, height_m_ieee754_class TEXT NOT NULL, sill_height_m_ieee754_bits INTEGER NOT NULL, sill_height_m_ieee754_class TEXT NOT NULL, frame_conductance_w_k_ieee754_bits INTEGER NOT NULL, frame_conductance_w_k_ieee754_class TEXT NOT NULL, divider_conductance_w_k_ieee754_bits INTEGER NOT NULL, divider_conductance_w_k_ieee754_class TEXT NOT NULL, overhang_depth_m_ieee754_bits INTEGER NOT NULL, overhang_depth_m_ieee754_class TEXT NOT NULL, overhang_offset_m_ieee754_bits INTEGER NOT NULL, overhang_offset_m_ieee754_class TEXT NOT NULL, fin_depth_m_ieee754_bits INTEGER NOT NULL, fin_depth_m_ieee754_class TEXT NOT NULL, fin_offset_m_ieee754_bits INTEGER NOT NULL, fin_offset_m_ieee754_class TEXT NOT NULL
);
CREATE TABLE energy_fenestration_vertex (id INTEGER PRIMARY KEY, fenestration_id INTEGER NOT NULL REFERENCES energy_fenestration(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), x_m REAL, y_m REAL, z_m REAL, x_m_ieee754_bits INTEGER NOT NULL, x_m_ieee754_class TEXT NOT NULL, y_m_ieee754_bits INTEGER NOT NULL, y_m_ieee754_class TEXT NOT NULL, z_m_ieee754_bits INTEGER NOT NULL, z_m_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_material (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), name TEXT NOT NULL, roughness TEXT NOT NULL CHECK(roughness IN ('VeryRough','Rough','MediumRough','MediumSmooth','Smooth','VerySmooth')), thickness_m REAL, conductivity_w_m_k REAL, density_kg_m3 REAL, specific_heat_j_kg_k REAL, thermal_absorptance REAL, solar_absorptance REAL, visible_absorptance REAL,
 thickness_m_ieee754_bits INTEGER NOT NULL, thickness_m_ieee754_class TEXT NOT NULL, conductivity_w_m_k_ieee754_bits INTEGER NOT NULL, conductivity_w_m_k_ieee754_class TEXT NOT NULL, density_kg_m3_ieee754_bits INTEGER NOT NULL, density_kg_m3_ieee754_class TEXT NOT NULL, specific_heat_j_kg_k_ieee754_bits INTEGER NOT NULL, specific_heat_j_kg_k_ieee754_class TEXT NOT NULL, thermal_absorptance_ieee754_bits INTEGER NOT NULL, thermal_absorptance_ieee754_class TEXT NOT NULL, solar_absorptance_ieee754_bits INTEGER NOT NULL, solar_absorptance_ieee754_class TEXT NOT NULL, visible_absorptance_ieee754_bits INTEGER NOT NULL, visible_absorptance_ieee754_class TEXT NOT NULL
);
CREATE TABLE energy_glazing_material (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), name TEXT NOT NULL, thickness_m REAL, conductivity_w_m_k REAL, solar_transmittance REAL, solar_reflectance_front REAL, solar_reflectance_back REAL, visible_transmittance REAL, visible_reflectance_front REAL, visible_reflectance_back REAL, infrared_transmittance REAL, infrared_emissivity_front REAL, infrared_emissivity_back REAL,
 thickness_m_ieee754_bits INTEGER NOT NULL, thickness_m_ieee754_class TEXT NOT NULL, conductivity_w_m_k_ieee754_bits INTEGER NOT NULL, conductivity_w_m_k_ieee754_class TEXT NOT NULL, solar_transmittance_ieee754_bits INTEGER NOT NULL, solar_transmittance_ieee754_class TEXT NOT NULL, solar_reflectance_front_ieee754_bits INTEGER NOT NULL, solar_reflectance_front_ieee754_class TEXT NOT NULL, solar_reflectance_back_ieee754_bits INTEGER NOT NULL, solar_reflectance_back_ieee754_class TEXT NOT NULL, visible_transmittance_ieee754_bits INTEGER NOT NULL, visible_transmittance_ieee754_class TEXT NOT NULL, visible_reflectance_front_ieee754_bits INTEGER NOT NULL, visible_reflectance_front_ieee754_class TEXT NOT NULL, visible_reflectance_back_ieee754_bits INTEGER NOT NULL, visible_reflectance_back_ieee754_class TEXT NOT NULL, infrared_transmittance_ieee754_bits INTEGER NOT NULL, infrared_transmittance_ieee754_class TEXT NOT NULL, infrared_emissivity_front_ieee754_bits INTEGER NOT NULL, infrared_emissivity_front_ieee754_class TEXT NOT NULL, infrared_emissivity_back_ieee754_bits INTEGER NOT NULL, infrared_emissivity_back_ieee754_class TEXT NOT NULL
);
CREATE TABLE energy_gas_material (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), name TEXT NOT NULL, thickness_m REAL, gas TEXT NOT NULL CHECK(gas IN ('Air','Argon','Krypton','Xenon')), thickness_m_ieee754_bits INTEGER NOT NULL, thickness_m_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_construction (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), name TEXT NOT NULL);
CREATE TABLE energy_construction_layer (id INTEGER PRIMARY KEY, construction_id INTEGER NOT NULL REFERENCES energy_construction(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), material_id INTEGER NOT NULL CHECK(material_id BETWEEN 0 AND 4294967295));
CREATE TABLE energy_people (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), zone_id INTEGER NOT NULL CHECK(zone_id BETWEEN 0 AND 4294967295), schedule_id INTEGER NOT NULL CHECK(schedule_id BETWEEN 0 AND 4294967295), activity_schedule_id INTEGER NOT NULL CHECK(activity_schedule_id BETWEEN 0 AND 4294967295), people_per_area REAL, sensible_fraction REAL, latent_fraction REAL, radiant_fraction REAL, people_per_area_ieee754_bits INTEGER NOT NULL, people_per_area_ieee754_class TEXT NOT NULL, sensible_fraction_ieee754_bits INTEGER NOT NULL, sensible_fraction_ieee754_class TEXT NOT NULL, latent_fraction_ieee754_bits INTEGER NOT NULL, latent_fraction_ieee754_class TEXT NOT NULL, radiant_fraction_ieee754_bits INTEGER NOT NULL, radiant_fraction_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_lighting (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), zone_id INTEGER NOT NULL CHECK(zone_id BETWEEN 0 AND 4294967295), schedule_id INTEGER NOT NULL CHECK(schedule_id BETWEEN 0 AND 4294967295), watts_per_area REAL, radiant_fraction REAL, visible_fraction REAL, return_air_fraction REAL, watts_per_area_ieee754_bits INTEGER NOT NULL, watts_per_area_ieee754_class TEXT NOT NULL, radiant_fraction_ieee754_bits INTEGER NOT NULL, radiant_fraction_ieee754_class TEXT NOT NULL, visible_fraction_ieee754_bits INTEGER NOT NULL, visible_fraction_ieee754_class TEXT NOT NULL, return_air_fraction_ieee754_bits INTEGER NOT NULL, return_air_fraction_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_equipment (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), zone_id INTEGER NOT NULL CHECK(zone_id BETWEEN 0 AND 4294967295), schedule_id INTEGER NOT NULL CHECK(schedule_id BETWEEN 0 AND 4294967295), watts_per_area REAL, radiant_fraction REAL, latent_fraction REAL, watts_per_area_ieee754_bits INTEGER NOT NULL, watts_per_area_ieee754_class TEXT NOT NULL, radiant_fraction_ieee754_bits INTEGER NOT NULL, radiant_fraction_ieee754_class TEXT NOT NULL, latent_fraction_ieee754_bits INTEGER NOT NULL, latent_fraction_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_thermostat (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), zone_id INTEGER NOT NULL CHECK(zone_id BETWEEN 0 AND 4294967295), heating_setpoint_schedule_id INTEGER NOT NULL CHECK(heating_setpoint_schedule_id BETWEEN 0 AND 4294967295), cooling_setpoint_schedule_id INTEGER NOT NULL CHECK(cooling_setpoint_schedule_id BETWEEN 0 AND 4294967295), heating_throttle_range_k REAL, cooling_throttle_range_k REAL, heating_throttle_range_k_ieee754_bits INTEGER NOT NULL, heating_throttle_range_k_ieee754_class TEXT NOT NULL, cooling_throttle_range_k_ieee754_bits INTEGER NOT NULL, cooling_throttle_range_k_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_humidistat (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), zone_id INTEGER NOT NULL CHECK(zone_id BETWEEN 0 AND 4294967295), humidifying_setpoint_schedule_id INTEGER NOT NULL CHECK(humidifying_setpoint_schedule_id BETWEEN 0 AND 4294967295), dehumidifying_setpoint_schedule_id INTEGER NOT NULL CHECK(dehumidifying_setpoint_schedule_id BETWEEN 0 AND 4294967295), humidifying_throttle_range REAL, dehumidifying_throttle_range REAL, humidifying_throttle_range_ieee754_bits INTEGER NOT NULL, humidifying_throttle_range_ieee754_class TEXT NOT NULL, dehumidifying_throttle_range_ieee754_bits INTEGER NOT NULL, dehumidifying_throttle_range_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_setpoint_manager (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('Scheduled','OutdoorAirReset','WarmestZone','ColdestZone')), schedule_id INTEGER CHECK(schedule_id BETWEEN 0 AND 4294967295));
CREATE TABLE energy_setpoint_outdoor_reset (id INTEGER PRIMARY KEY REFERENCES energy_setpoint_manager(id), low_outdoor_c REAL, high_outdoor_c REAL, low_setpoint_c REAL, high_setpoint_c REAL, low_outdoor_c_ieee754_bits INTEGER NOT NULL, low_outdoor_c_ieee754_class TEXT NOT NULL, high_outdoor_c_ieee754_bits INTEGER NOT NULL, high_outdoor_c_ieee754_class TEXT NOT NULL, low_setpoint_c_ieee754_bits INTEGER NOT NULL, low_setpoint_c_ieee754_class TEXT NOT NULL, high_setpoint_c_ieee754_bits INTEGER NOT NULL, high_setpoint_c_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_ideal_loads (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), zone_id INTEGER NOT NULL CHECK(zone_id BETWEEN 0 AND 4294967295), max_heating_supply_air_temp_c REAL, min_cooling_supply_air_temp_c REAL, max_heating_capacity_w REAL, max_cooling_capacity_w REAL, outdoor_air_per_person_m3_s REAL, outdoor_air_per_area_m3_s_m2 REAL, max_heating_supply_air_temp_c_ieee754_bits INTEGER NOT NULL, max_heating_supply_air_temp_c_ieee754_class TEXT NOT NULL, min_cooling_supply_air_temp_c_ieee754_bits INTEGER NOT NULL, min_cooling_supply_air_temp_c_ieee754_class TEXT NOT NULL, max_heating_capacity_w_ieee754_bits INTEGER, max_heating_capacity_w_ieee754_class TEXT, max_cooling_capacity_w_ieee754_bits INTEGER, max_cooling_capacity_w_ieee754_class TEXT, outdoor_air_per_person_m3_s_ieee754_bits INTEGER NOT NULL, outdoor_air_per_person_m3_s_ieee754_class TEXT NOT NULL, outdoor_air_per_area_m3_s_m2_ieee754_bits INTEGER NOT NULL, outdoor_air_per_area_m3_s_m2_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_zone_equipment (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), zone_id INTEGER NOT NULL CHECK(zone_id BETWEEN 0 AND 4294967295), equipment_type TEXT NOT NULL CHECK(equipment_type IN ('Baseboard','Radiant','FanCoil','Ptac','VrfTerminal','Erv','UnitHeater','WaterToAirHp')), priority INTEGER NOT NULL CHECK(priority BETWEEN 0 AND 255), heating_capacity_w REAL, cooling_capacity_w REAL, heating_capacity_w_ieee754_bits INTEGER NOT NULL, heating_capacity_w_ieee754_class TEXT NOT NULL, cooling_capacity_w_ieee754_bits INTEGER NOT NULL, cooling_capacity_w_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_air_loop (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), name TEXT NOT NULL, supply_node_id INTEGER NOT NULL CHECK(supply_node_id BETWEEN 0 AND 4294967295), return_node_id INTEGER NOT NULL CHECK(return_node_id BETWEEN 0 AND 4294967295), design_supply_air_flow_m3_s REAL, design_supply_air_flow_m3_s_ieee754_bits INTEGER NOT NULL, design_supply_air_flow_m3_s_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_air_loop_terminal (id INTEGER PRIMARY KEY, air_loop_id INTEGER NOT NULL REFERENCES energy_air_loop(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), zone_id INTEGER NOT NULL CHECK(zone_id BETWEEN 0 AND 4294967295));
CREATE TABLE energy_plant_loop (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), name TEXT NOT NULL, loop_type TEXT NOT NULL CHECK(loop_type IN ('Heating','Cooling','Condenser')), supply_temperature_c REAL, return_temperature_c REAL, design_flow_kg_s REAL, supply_temperature_c_ieee754_bits INTEGER NOT NULL, supply_temperature_c_ieee754_class TEXT NOT NULL, return_temperature_c_ieee754_bits INTEGER NOT NULL, return_temperature_c_ieee754_class TEXT NOT NULL, design_flow_kg_s_ieee754_bits INTEGER NOT NULL, design_flow_kg_s_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_plant_loop_equipment (id INTEGER PRIMARY KEY, plant_loop_id INTEGER NOT NULL REFERENCES energy_plant_loop(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), equipment_id INTEGER NOT NULL CHECK(equipment_id BETWEEN 0 AND 4294967295));
CREATE TABLE energy_outdoor_air_system (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), air_loop_id INTEGER NOT NULL CHECK(air_loop_id BETWEEN 0 AND 4294967295), min_oa_flow_m3_s REAL, economizer_enabled INTEGER NOT NULL CHECK(economizer_enabled IN (0,1)), min_oa_flow_m3_s_ieee754_bits INTEGER NOT NULL, min_oa_flow_m3_s_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_infiltration (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), zone_id INTEGER NOT NULL CHECK(zone_id BETWEEN 0 AND 4294967295), schedule_id INTEGER NOT NULL CHECK(schedule_id BETWEEN 0 AND 4294967295), method TEXT NOT NULL CHECK(method IN ('ScheduledAch','PerExteriorArea','EffectiveLeakageArea','WindAndStack')), design_flow_ach REAL, flow_per_exterior_area_m3_s_m2 REAL, effective_leakage_area_m2 REAL, discharge_coefficient REAL, stack_height_m REAL, constant_term_coefficient REAL, temperature_term_coefficient REAL, velocity_term_coefficient REAL, velocity_squared_term_coefficient REAL,
 design_flow_ach_ieee754_bits INTEGER NOT NULL, design_flow_ach_ieee754_class TEXT NOT NULL, flow_per_exterior_area_m3_s_m2_ieee754_bits INTEGER NOT NULL, flow_per_exterior_area_m3_s_m2_ieee754_class TEXT NOT NULL, effective_leakage_area_m2_ieee754_bits INTEGER NOT NULL, effective_leakage_area_m2_ieee754_class TEXT NOT NULL, discharge_coefficient_ieee754_bits INTEGER NOT NULL, discharge_coefficient_ieee754_class TEXT NOT NULL, stack_height_m_ieee754_bits INTEGER NOT NULL, stack_height_m_ieee754_class TEXT NOT NULL, constant_term_coefficient_ieee754_bits INTEGER NOT NULL, constant_term_coefficient_ieee754_class TEXT NOT NULL, temperature_term_coefficient_ieee754_bits INTEGER NOT NULL, temperature_term_coefficient_ieee754_class TEXT NOT NULL, velocity_term_coefficient_ieee754_bits INTEGER NOT NULL, velocity_term_coefficient_ieee754_class TEXT NOT NULL, velocity_squared_term_coefficient_ieee754_bits INTEGER NOT NULL, velocity_squared_term_coefficient_ieee754_class TEXT NOT NULL
);
CREATE TABLE energy_mechanical_ventilation (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), zone_id INTEGER NOT NULL CHECK(zone_id BETWEEN 0 AND 4294967295), schedule_id INTEGER NOT NULL CHECK(schedule_id BETWEEN 0 AND 4294967295), design_flow_m3_s REAL, fan_total_efficiency REAL, fan_delta_pressure_pa REAL, design_flow_m3_s_ieee754_bits INTEGER NOT NULL, design_flow_m3_s_ieee754_class TEXT NOT NULL, fan_total_efficiency_ieee754_bits INTEGER NOT NULL, fan_total_efficiency_ieee754_class TEXT NOT NULL, fan_delta_pressure_pa_ieee754_bits INTEGER NOT NULL, fan_delta_pressure_pa_ieee754_class TEXT NOT NULL);
