CREATE TABLE energy_space_list (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), name TEXT NOT NULL);
CREATE TABLE energy_space_list_member (id INTEGER PRIMARY KEY, space_list_id INTEGER NOT NULL REFERENCES energy_space_list(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), space_id INTEGER NOT NULL CHECK(space_id BETWEEN 0 AND 4294967295));
CREATE TABLE energy_thermal_enclosure (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), name TEXT NOT NULL);
