CREATE TABLE energy_electrical_pv (id INTEGER PRIMARY KEY, load_center_id INTEGER NOT NULL REFERENCES energy_electrical_load_center(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), pv_id INTEGER NOT NULL CHECK(pv_id BETWEEN 0 AND 4294967295));
CREATE TABLE energy_electrical_battery (id INTEGER PRIMARY KEY, load_center_id INTEGER NOT NULL REFERENCES energy_electrical_load_center(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), battery_id INTEGER NOT NULL CHECK(battery_id BETWEEN 0 AND 4294967295));
CREATE TABLE energy_pv_system (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), dc_capacity_w REAL, area_m2 REAL, tilt_deg REAL, azimuth_deg REAL, module_efficiency REAL, inverter_efficiency REAL, dc_capacity_w_ieee754_bits INTEGER NOT NULL, dc_capacity_w_ieee754_class TEXT NOT NULL, area_m2_ieee754_bits INTEGER NOT NULL, area_m2_ieee754_class TEXT NOT NULL, tilt_deg_ieee754_bits INTEGER NOT NULL, tilt_deg_ieee754_class TEXT NOT NULL, azimuth_deg_ieee754_bits INTEGER NOT NULL, azimuth_deg_ieee754_class TEXT NOT NULL, module_efficiency_ieee754_bits INTEGER NOT NULL, module_efficiency_ieee754_class TEXT NOT NULL, inverter_efficiency_ieee754_bits INTEGER NOT NULL, inverter_efficiency_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_battery (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), capacity_kwh REAL, max_charge_w REAL, max_discharge_w REAL, round_trip_efficiency REAL, capacity_kwh_ieee754_bits INTEGER NOT NULL, capacity_kwh_ieee754_class TEXT NOT NULL, max_charge_w_ieee754_bits INTEGER NOT NULL, max_charge_w_ieee754_class TEXT NOT NULL, max_discharge_w_ieee754_bits INTEGER NOT NULL, max_discharge_w_ieee754_class TEXT NOT NULL, round_trip_efficiency_ieee754_bits INTEGER NOT NULL, round_trip_efficiency_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_shw_system (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), heater_capacity_w REAL, storage_volume_m3 REAL, setpoint_c REAL, schedule_id INTEGER NOT NULL CHECK(schedule_id BETWEEN 0 AND 4294967295), heater_capacity_w_ieee754_bits INTEGER NOT NULL, heater_capacity_w_ieee754_class TEXT NOT NULL, storage_volume_m3_ieee754_bits INTEGER NOT NULL, storage_volume_m3_ieee754_class TEXT NOT NULL, setpoint_c_ieee754_bits INTEGER NOT NULL, setpoint_c_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_solar_thermal (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), collector_area_m2 REAL, efficiency REAL, storage_volume_m3 REAL, tilt_deg REAL, azimuth_deg REAL, collector_area_m2_ieee754_bits INTEGER NOT NULL, collector_area_m2_ieee754_class TEXT NOT NULL, efficiency_ieee754_bits INTEGER NOT NULL, efficiency_ieee754_class TEXT NOT NULL, storage_volume_m3_ieee754_bits INTEGER NOT NULL, storage_volume_m3_ieee754_class TEXT NOT NULL, tilt_deg_ieee754_bits INTEGER NOT NULL, tilt_deg_ieee754_class TEXT NOT NULL, azimuth_deg_ieee754_bits INTEGER NOT NULL, azimuth_deg_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_refrigeration (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), case_count INTEGER NOT NULL CHECK(case_count BETWEEN 0 AND 4294967295), design_load_w REAL, defrost_schedule_id INTEGER NOT NULL CHECK(defrost_schedule_id BETWEEN 0 AND 4294967295), design_load_w_ieee754_bits INTEGER NOT NULL, design_load_w_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_water_system (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), fixture_count INTEGER NOT NULL CHECK(fixture_count BETWEEN 0 AND 4294967295), peak_flow_l_s REAL, schedule_id INTEGER NOT NULL CHECK(schedule_id BETWEEN 0 AND 4294967295), peak_flow_l_s_ieee754_bits INTEGER NOT NULL, peak_flow_l_s_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_fault (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), target_equipment_id INTEGER NOT NULL CHECK(target_equipment_id BETWEEN 0 AND 4294967295), fault_type TEXT NOT NULL CHECK(fault_type IN ('SensorBias','CoilFouling','DamperStuck','ChillerFouling','BoilerEfficiencyDegradation')), severity REAL, start_schedule_id INTEGER NOT NULL CHECK(start_schedule_id BETWEEN 0 AND 4294967295), severity_ieee754_bits INTEGER NOT NULL, severity_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_output_variable (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), name TEXT NOT NULL, key TEXT NOT NULL, reporting_frequency TEXT NOT NULL CHECK(reporting_frequency IN ('Timestep','Hourly','Daily','Monthly','RunPeriod')));
CREATE TABLE energy_sizing_object (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), zone_id INTEGER NOT NULL CHECK(zone_id BETWEEN 0 AND 4294967295), sizing_type TEXT NOT NULL CHECK(sizing_type IN ('Heating','Cooling','OutdoorAir')), design_day_type TEXT NOT NULL CHECK(design_day_type IN ('Heating','Cooling')));
CREATE TABLE energy_daylight_zone (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), entity_id INTEGER NOT NULL CHECK(entity_id BETWEEN 0 AND 4294967295), zone_id INTEGER NOT NULL CHECK(zone_id BETWEEN 0 AND 4294967295), illuminance_target_lux REAL, glare_limit REAL, window_transmittance REAL, illuminance_target_lux_ieee754_bits INTEGER NOT NULL, illuminance_target_lux_ieee754_class TEXT NOT NULL, glare_limit_ieee754_bits INTEGER NOT NULL, glare_limit_ieee754_class TEXT NOT NULL, window_transmittance_ieee754_bits INTEGER NOT NULL, window_transmittance_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_room_air_model (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), zone_id INTEGER NOT NULL CHECK(zone_id BETWEEN 0 AND 4294967295), model TEXT NOT NULL CHECK(model IN ('WellMixed','OneNodeDisplacement','TwoNodeBuoyancy','UnderFloorAirDistribution')));
CREATE TABLE energy_constant_schedule (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), schedule_id INTEGER NOT NULL CHECK(schedule_id BETWEEN 0 AND 4294967295), value REAL, value_ieee754_bits INTEGER NOT NULL, value_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_daily_schedule (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), schedule_id INTEGER NOT NULL CHECK(schedule_id BETWEEN 0 AND 4294967295), interpolation TEXT NOT NULL CHECK(interpolation IN ('Continuous','Discrete')));
CREATE TABLE energy_daily_hour (id INTEGER PRIMARY KEY, schedule_id INTEGER NOT NULL REFERENCES energy_daily_schedule(id), ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 23), value REAL, value_ieee754_bits INTEGER NOT NULL, value_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_daily_limits (id INTEGER PRIMARY KEY REFERENCES energy_daily_schedule(id), min REAL, max REAL, min_ieee754_bits INTEGER NOT NULL, min_ieee754_class TEXT NOT NULL, max_ieee754_bits INTEGER NOT NULL, max_ieee754_class TEXT NOT NULL);
CREATE TABLE energy_weekly_schedule (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), schedule_id INTEGER NOT NULL CHECK(schedule_id BETWEEN 0 AND 4294967295));
CREATE TABLE energy_weekly_day (id INTEGER PRIMARY KEY, schedule_id INTEGER NOT NULL REFERENCES energy_weekly_schedule(id), ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 6), daily_schedule_id INTEGER NOT NULL CHECK(daily_schedule_id BETWEEN 0 AND 4294967295));
CREATE TABLE energy_annual_schedule (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), schedule_id INTEGER NOT NULL CHECK(schedule_id BETWEEN 0 AND 4294967295), default_daily_schedule_id INTEGER NOT NULL CHECK(default_daily_schedule_id BETWEEN 0 AND 4294967295), holiday_daily_schedule_id INTEGER CHECK(holiday_daily_schedule_id BETWEEN 0 AND 4294967295));
CREATE TABLE energy_annual_rule (id INTEGER PRIMARY KEY, schedule_id INTEGER NOT NULL REFERENCES energy_annual_schedule(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), start_month INTEGER NOT NULL CHECK(start_month BETWEEN 0 AND 255), start_day INTEGER NOT NULL CHECK(start_day BETWEEN 0 AND 255), end_month INTEGER NOT NULL CHECK(end_month BETWEEN 0 AND 255), end_day INTEGER NOT NULL CHECK(end_day BETWEEN 0 AND 255), daily_schedule_id INTEGER NOT NULL CHECK(daily_schedule_id BETWEEN 0 AND 4294967295));
CREATE TABLE energy_annual_holiday (id INTEGER PRIMARY KEY, schedule_id INTEGER NOT NULL REFERENCES energy_annual_schedule(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), year INTEGER NOT NULL CHECK(year BETWEEN 0 AND 65535), month INTEGER NOT NULL CHECK(month BETWEEN 0 AND 255), day INTEGER NOT NULL CHECK(day BETWEEN 0 AND 255));
CREATE TABLE energy_time_series_schedule (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES energy_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), schedule_id INTEGER NOT NULL CHECK(schedule_id BETWEEN 0 AND 4294967295), timestep_seconds INTEGER NOT NULL CHECK(timestep_seconds BETWEEN 0 AND 4294967295));
CREATE TABLE energy_time_series_value (id INTEGER PRIMARY KEY, schedule_id INTEGER NOT NULL REFERENCES energy_time_series_schedule(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value REAL, value_ieee754_bits INTEGER NOT NULL, value_ieee754_class TEXT NOT NULL);
